import type { FontWeight } from '@canvas/schema';

import type { FontMetrics } from '../font/font-metrics.js';

import { COVERAGE_FACES } from './coverage-generated/index.js';
import { decodeFaceMetrics } from './face-encoding.js';

/** One symbol face's encoded metrics (generated by coverage-font-metrics.test.ts). */
export interface EncodedCoverageFace {
  /** The face's family. */
  readonly family: string;
  /** Its weight. */
  readonly weight: FontWeight;
  /** Whether it is italic. */
  readonly isItalic: boolean;
  /** Its metrics, encoded (`encodeFaceMetrics`). */
  readonly metrics: string;
}

let decoded: readonly FontMetrics[] | undefined;

/**
 * The symbol faces' metrics (Noto Sans Math, Noto Sans Symbols 2), in fallback order,
 * exactly as the app's font library measures them once their files are loaded. Decoded once, when
 * first asked for.
 *
 * @returns The faces' metrics.
 */
export function symbolCoverageMetrics(): readonly FontMetrics[] {
  decoded ??= COVERAGE_FACES.map(({ family, weight, isItalic, metrics }) =>
    decodeFaceMetrics({ family, weight, isItalic }, metrics),
  );
  return decoded;
}
